import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"简介","description":"KiriVers 是自托管软件更新服务：你发布产物，应用来检查并下载更新。","frontmatter":{"title":"简介","description":"KiriVers 是自托管软件更新服务：你发布产物，应用来检查并下载更新。"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1790057721000}`),a={name:`guide/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><p>KiriVers 是<strong>自托管软件更新服务</strong>。你发布安装包或固件；用户设备上的应用向本服务查询并下载更新。它不是 git，也不能替代 App Store、Google Play 或 Microsoft Store 的上架审核。</p><h2 id="运行形态" tabindex="-1">运行形态 <a class="header-anchor" href="#运行形态" aria-label="Permalink to “运行形态”">​</a></h2><p>单进程提供两个平面（plane）：</p><table tabindex="0"><thead><tr><th>平面</th><th>默认地址</th><th>职责</th></tr></thead><tbody><tr><td>客户端平面</td><td><code>:8080</code></td><td>检查更新、下载、商店 feed、遥测、公告</td></tr><tr><td>管理平面</td><td><code>:8081</code></td><td>管理台 SPA 与 CI Agent</td></tr></tbody></table><p>官方 Releases 可执行文件已 <code>go:embed</code> 管理台。使用者不必再部署前端静态文件。PostgreSQL 必需；Redis 可选（见<a href="/guide/install/">安装</a>与<a href="/guide/config/cache">缓存</a>）。</p><p>CLI 仅有 <code>kirivers</code> / <code>kirivers server</code>，以及本机 <code>kirivers admin add|delete|list|reset-password|clear-2fa</code>。没有发版子命令，也没有 <code>kirivers listen</code>。</p><h2 id="接入两条路" tabindex="-1">接入两条路 <a class="header-anchor" href="#接入两条路" aria-label="Permalink to “接入两条路”">​</a></h2><ol><li><strong>原生 JSON</strong>：应用直接调用客户端平面（<code>POST .../update/check</code>）。适合自制桌面、服务、固件客户端。官方 <a href="/api/sdk/">SDK</a> 只封装这条路径。</li><li><strong>商店订阅</strong>：在管理台创建 listing，把 URL 填进 Electron / Sparkle / Tauri 等现成更新器。原生 SDK <strong>不</strong>读 feed。</li></ol><h2 id="做不到的事" tabindex="-1">做不到的事 <a class="header-anchor" href="#做不到的事" aria-label="Permalink to “做不到的事”">​</a></h2><ul><li>代替各商店的上架与审核。</li><li>充当 Linux 系统软件源（APT / RPM / Flatpak）。</li><li>用管理平面 <code>GET /</code> 托管本站文档。</li></ul><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to “阅读顺序”">​</a></h2><ol><li><a href="/guide/install/">选择安装方式</a> → 配置 YAML → <a href="/guide/config/bootstrap-admin">创建第一个管理员</a></li><li>登录后按 <a href="/admin/quick-start">管理 → 快速上手</a> 发出第一个版本</li><li>用 <a href="/guide/features/">功能指南</a> 理解渠道、灰度、增量、公告等</li><li>再按软件类型阅读 <a href="/guide/scenarios/">使用场景</a></li></ol>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};